const baseUrl = String(
  $json.accept_url_base ??
  $json.proposal_accept_url ??
  $json.accept_url ??
  ''
);

const token = String($json.accept_token ?? '');

if (!baseUrl) {
  throw new Error('3.0.1.2: proposal accept URL is missing');
}

if (!token) {
  throw new Error('3.0.1.2: accept_token is missing');
}

// Preserve existing query parameters and append the signed token.
const separator = baseUrl.includes('?') ? '&' : '?';
const acceptUrl = `${baseUrl}${separator}accept_token=${encodeURIComponent(token)}`;

return [{
  json: {
    ...$json,
    proposal_accept_url: acceptUrl
  }
}];
